mapper.update:
UPDATE ai_diagnostic_runs
SET status = #{run.status}, result_json = #{run.resultJson}, input_tokens = #{run.inputTokens},
    output_tokens = #{run.outputTokens}, total_tokens = #{run.totalTokens},
    duration_ms = #{run.durationMs}, completed_at = #{run.completedAt}
WHERE id = #{run.id}

UPDATE ai_diagnostic_runs
SET status = #{run.status}, error_code = #{run.errorCode}, duration_ms = #{run.durationMs},
    completed_at = #{run.completedAt}
WHERE id = #{run.id}

mapper.delete:
DELETE FROM ai_diagnostic_runs
WHERE created_at < #{cutoffTime}
ORDER BY id
LIMIT #{batchSize}

mapper.select:
SELECT COALESCE(SUM(total_tokens), 0)
FROM ai_diagnostic_runs
WHERE status = 'completed'
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
